const fs = require('fs');
const cp = require('child_process');

console.log('=== original run.js ===');
console.log(fs.readFileSync('run.js', 'utf8'));

const fixed = String.raw`const fs = require('fs');
const path = require('path');

const N = Number(process.argv[2] || 0);

const counterFile = path.join(__dirname, 'counter.json');
const logFile = path.join(__dirname, 'log.txt');

// 启动时重置
fs.writeFileSync(counterFile, JSON.stringify({ n: 0 }));
fs.writeFileSync(logFile, '');

// 单写者串行化：所有读-改-写+追加都排在同一条 promise 链上，杜绝丢更新
let tail = Promise.resolve();
function withLock(fn) {
  const p = tail.then(fn, fn);
  tail = p.then(function () {}, function () {});
  return p;
}

function task() {
  return withLock(function () {
    const data = JSON.parse(fs.readFileSync(counterFile, 'utf8'));
    data.n += 1;
    fs.writeFileSync(counterFile, JSON.stringify(data));
    fs.appendFileSync(logFile, 'tick' + '\n');
  });
}

const jobs = [];
for (let i = 0; i < N; i++) jobs.push(task());

Promise.all(jobs).then(function () {
  const data = JSON.parse(fs.readFileSync(counterFile, 'utf8'));
  console.log('n=' + data.n);
});
`;

fs.writeFileSync('run.js', fixed);
console.log('=== run.js rewritten (single-writer lock) ===');

function check(N) {
  const r = cp.spawnSync(process.execPath, ['run.js', String(N)], { cwd: process.cwd(), encoding: 'utf8' });
  const counter = JSON.parse(fs.readFileSync('counter.json', 'utf8'));
  const raw = fs.readFileSync('log.txt', 'utf8');
  const lines = raw.length ? raw.replace(/\n$/, '').split('\n').length : 0;
  const out = (r.stdout || '').trim();
  const ok = out === 'n=' + N && counter.n === N && lines === N && r.status === 0;
  console.log('--- N=' + N + ' ---');
  console.log('stdout: ' + JSON.stringify(out));
  if ((r.stderr || '').trim()) console.log('stderr: ' + JSON.stringify(r.stderr.trim()));
  console.log('counter.json n=' + counter.n + ' | log.txt lines=' + lines + ' | exit=' + r.status + ' | PASS=' + ok);
  if (!ok) { console.log('DONE: FAILED'); process.exit(1); }
}

check(3);
check(7);
console.log('DONE: race fixed (single-writer lock); N=3 and N=7 each give n=N, N log lines, stdout n=N');

